#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array({10, 20, 30});
        nlohmann::json_pointer<std::string> ptr("/1");
        std::cout << "pointer evaluation: " << j[ptr].get<int>() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << typeid(e).name() << " " << e.what() << "\n";
    }
    return 0;
}
